using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using System.Text.RegularExpressions;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Colors;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoColor{
 const string Work=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";
 public class Row{public string Title{get;set;}public string[] Handles{get;set;}public string Source{get;set;}}
 static ObjectId Id(Database db,string h)=>db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0);
 static Color Effective(Entity e,Transaction tr,ObjectId inheritedLayer,Color inheritedColor,out ObjectId layer){layer=e.LayerId;var l=(LayerTableRecord)tr.GetObject(layer,OpenMode.ForRead);if(l.Name=="0"&&!inheritedLayer.IsNull){layer=inheritedLayer;l=(LayerTableRecord)tr.GetObject(layer,OpenMode.ForRead);}return e.Color.ColorMethod switch {ColorMethod.ByLayer=>l.Color,ColorMethod.ByBlock=>inheritedColor??l.Color,_=>e.Color};}
 static void Flatten(Entity e,Transaction tr,HashSet<string> annotations,List<Color> colors,ObjectId inheritedLayer,Color inheritedColor,int depth=0){try{if(depth>8||!e.Visible||e is AttributeDefinition||e is AttributeReference)return;var color=Effective(e,tr,inheritedLayer,inheritedColor,out var layer);if(e is BlockReference){var kids=new DBObjectCollection();e.Explode(kids);foreach(DBObject o in kids){if(o is Entity child)Flatten(child,tr,annotations,colors,layer,color,depth+1);else o.Dispose();}return;}if(e is DBText t&&annotations.Contains(t.TextString))return;if(e is MText m&&annotations.Contains(m.Text))return;colors.Add(color);}finally{e.Dispose();}}
 [CommandMethod("CODEXUGORESTORECOLORS",CommandFlags.Session)]public void Run(){try{
 var rows=JsonSerializer.Deserialize<Row[]>(File.ReadAllText(Path.Combine(Work,"update_rows.json")));var target=JsonDocument.Parse(File.ReadAllText(Path.Combine(Work,"added.json"))).RootElement.GetProperty("File").GetString();var docs=AcApp.DocumentManager.Cast<Autodesk.AutoCAD.ApplicationServices.Document>().ToArray();var doc=docs.Single(d=>d.Name.Equals(target,StringComparison.OrdinalIgnoreCase));var plans=docs.Single(d=>Path.GetFileName(d.Name).Equals("03_Чертежи ЭОМ_ХБК.dwg",StringComparison.OrdinalIgnoreCase));
 var palettes=new List<Color[]>();var sourceReport=new List<object>();using(var donor=new Database(false,true)){donor.ReadDwgFile(Path.Combine(Work,"УГО_ХБК_проверка.dwg"),FileOpenMode.OpenForReadAndAllShare,true,null);donor.CloseInput(true);foreach(var row in rows){var src=row.Source=="Plan"?plans.Database:donor;var colors=new List<Color>();using(var tr=src.TransactionManager.StartTransaction()){foreach(var handle in row.Handles){var e=(Entity)tr.GetObject(Id(src,handle),OpenMode.ForRead);var annotations=new HashSet<string>();var rootColor=Effective(e,tr,ObjectId.Null,null,out var rootLayer);if(e is BlockReference b)foreach(ObjectId aid in b.AttributeCollection){var a=(AttributeReference)tr.GetObject(aid,OpenMode.ForRead);if(a.Tag=="COUNT"){colors.Add(Effective(a,tr,rootLayer,rootColor,out var al));continue;}if(!string.IsNullOrWhiteSpace(a.TextString))annotations.Add(a.TextString);}Flatten((Entity)e.Clone(),tr,annotations,colors,ObjectId.Null,null);sourceReport.Add(new{row.Title,Handle=handle,Layer=e.Layer,RootColor=rootColor.ToString()});}}palettes.Add(colors.ToArray());}}
 using(var locked=doc.LockDocument()){var db=doc.Database;ObjectId[] definitions;using(var tr=db.TransactionManager.StartTransaction()){var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);var lay=(Layout)tr.GetObject(ld.GetAt("УГО"),OpenMode.ForRead);var paper=(BlockTableRecord)tr.GetObject(lay.BlockTableRecordId,OpenMode.ForRead);var blocks=paper.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<BlockReference>().Where(b=>tr.GetObject(b.BlockTableRecord,OpenMode.ForRead) is BlockTableRecord bt&&bt.Name.Contains("CODEX_HBK_UGO_")).ToArray();if(blocks.Length!=39)throw new System.Exception("Expected 39 symbols");definitions=new ObjectId[39];foreach(var b in blocks){var bt=(BlockTableRecord)tr.GetObject(b.BlockTableRecord,OpenMode.ForRead);int index=int.Parse(Regex.Match(bt.Name,@"CODEX_HBK_UGO_(\d+)$").Groups[1].Value)-1;definitions[index]=b.BlockTableRecord;if(bt.Cast<ObjectId>().Count()!=palettes[index].Length)throw new System.Exception("Part count differs for "+rows[index].Title+": "+bt.Cast<ObjectId>().Count()+" vs "+palettes[index].Length);}}
 var backup=Path.Combine(Work,"УГО_до_цветов_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".dwg");using(var copy=db.Wblock())copy.SaveAs(backup,DwgVersion.Current);var changed=0;using(var tr=db.TransactionManager.StartTransaction()){for(int i=0;i<39;i++){var bt=(BlockTableRecord)tr.GetObject(definitions[i],OpenMode.ForRead);int j=0;foreach(ObjectId id in bt){var e=(Entity)tr.GetObject(id,OpenMode.ForWrite);e.Color=palettes[i][j++];changed++;}}tr.Commit();}doc.Editor.Regen();File.WriteAllText(Path.Combine(Work,"color_result.json"),JsonSerializer.Serialize(new{File=target,Backup=backup,Symbols=39,Parts=changed,Sources=sourceReport,Palettes=palettes.Select((p,i)=>new{rows[i].Title,Colors=p.Select(c=>c.ToString()).ToArray()}).ToArray()},new JsonSerializerOptions{WriteIndented=true}));}
 }catch(System.Exception e){File.WriteAllText(Path.Combine(Work,"color_error.txt"),e.ToString());}}
}
